require_once __DIR__ . '/../includes/auth.php';require_once __DIR__ . '/../includes/mailer.php';$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$email=trim(strtolower($_POST['email']??''));$s=db()->prepare('SELECT id,full_name,email FROM reviewers WHERE email=? AND is_active=1 LIMIT 1');$s->bind_param('s',$email);$s->execute();$r=$s->get_result()->fetch_assoc();if($r){$token=bin2hex(random_bytes(32));$hash=hash('sha256',$token);$expires=date('Y-m-d H:i:s',time()+3600);$id=(int)$r['id'];$i=db()->prepare('INSERT INTO review_password_resets(reviewer_id,token_hash,expires_at,created_at) VALUES(?,?,?,NOW())');$i->bind_param('iss',$id,$hash,$expires);$i->execute();$link=APP_URL.'/reviewer/reset-password.php?token='.urlencode($token);send_mail($r['email'],'IRIA 2027 – Password Reset',mail_shell('Password Reset','<p>Dear '.htmlspecialchars($r['full_name']).',</p><p><a href="'.$link.'">Reset your password</a></p><p>This link expires in 1 hour.</p>'));}$message='If the email exists, a reset link has been sent.';}
$pageTitle='Forgot Password';require __DIR__ . '/../includes/header.php';?>
